import {fishClarity} from './fish-waste.js';
import {fishCount,fishBiomass,fishStage} from './fish-state.js';
/** Read-only scene projection. Preview data never enters the farm state or persistence. @param {import('./engine.js').State} state */
export function fishSnapshot(state){const g=state.fish;if(!g?.visited)return {preview:true,count:12,ready:4,biomassG:2240,ponds:[{id:1,count:12,ready:4,biomassG:2240,cohorts:[{count:4,massG:500},{count:8,massG:30}],aeratorOn:false,aerating:false,efficient:false,oxygenMg:28000,tanMg:400,clarity:980,feeding:false}]};return {preview:false,count:g.ponds.reduce((n,p)=>n+fishCount(p),0),ready:g.ponds.reduce((n,p)=>n+p.cohorts.filter(c=>fishStage(c,state.tick)==='ready').reduce((a,c)=>a+c.count,0),0),biomassG:g.ponds.reduce((n,p)=>n+fishBiomass(p),0),ponds:g.ponds.map(p=>({id:p.id,count:fishCount(p),ready:p.cohorts.filter(c=>fishStage(c,state.tick)==='ready').reduce((n,c)=>n+c.count,0),biomassG:fishBiomass(p),cohorts:p.cohorts.map(c=>({count:c.count,massG:c.massG})),aeratorOn:p.aeratorOn,aerating:p.aeratorOn&&p.serviceStatus==='running',efficient:p.efficient,oxygenMg:p.oxygenMg,tanMg:p.tanMg,clarity:fishClarity(p),feeding:p.pendingFeedG>0&&p.lastFeedTick===state.tick}))};}
